#!/usr/bin/env bash
# R1 (docs/sdd/token-budget-guard): token-budget.json is the single baseline, generated by token-measure.py
# from a release commit that it names. A missing or broken budget fails closed; main passes at 0 increase.
. "$(dirname "$0")/lib.sh"; . "$(dirname "$0")/token-budget-helpers.sh"
W="$(mktemp -d)"; trap 'rm -rf "$W"' EXIT
B="$REPO_ROOT/token-budget.json"
if [ -f "$B" ]; then
  ok "R1: token-budget.json exists"
  tag="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["tag"])' "$B")"
  commit="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["commit"])' "$B")"
  [[ "$tag" =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]] && [[ "$commit" =~ ^[0-9a-f]{40}$ ]] && ok "R1: budget names its release tag ($tag) and full commit" || fail "R1: tag '$tag' commit '$commit'"
  if git -C "$REPO_ROOT" rev-parse -q --verify "refs/tags/$tag" >/dev/null; then
    [ "$(git -C "$REPO_ROOT" rev-list -n1 "$tag")" = "$commit" ] && ok "R1: $tag points at the budget commit" || fail "R1: $tag is $(git -C "$REPO_ROOT" rev-list -n1 "$tag"), budget says $commit"
  fi
  mkdir -p "$W/rel"; git -C "$REPO_ROOT" archive "$commit" | tar -x -C "$W/rel"
  python3 "$TM" budget --root "$W/rel" --tag "$tag" --commit "$commit" --out "$W/regen.json" --selftest-repo "$REPO_ROOT" >/dev/null 2>&1
  python3 - "$B" "$W/regen.json" <<'PY' && ok "R1: budget numbers equal token-measure.py on $tag" || fail "R1: budget differs from a fresh measurement of $tag"
import json,sys; a,b=(json.load(open(p)) for p in sys.argv[1:]); sys.exit(0 if (a["skills"],a["always_on"])==(b["skills"],b["always_on"]) else 1)
PY
else
  fail "R1: token-budget.json missing"
fi
expect_exit 0 "R1: the current tree passes the budget (0 increase)" -- python3 "$TM" check --root "$REPO_ROOT" --budget "$B" --selftest-repo "$REPO_ROOT"
expect_exit 2 "R1: a missing budget fails closed" -- python3 "$TM" check --root "$REPO_ROOT" --budget "$W/none.json" --selftest-repo "$REPO_ROOT"
echo '{"skills": 3}' > "$W/bad.json"
expect_exit 2 "R1: a malformed budget fails closed" -- python3 "$TM" check --root "$REPO_ROOT" --budget "$W/bad.json" --selftest-repo "$REPO_ROOT"
finish
